//! Wi-Fi over Messenger (`idl/wifi.midl`, docs/architecture/wifi.md):
//!
//! * [`Radio`]: the client side of `os.lazy.net.wifi.hw.v1`, a radio driver
//!   (`wifid`, `wifisim`) as `wlanmd` uses it; radios are found by
//!   [`radios`] under `os.lazy.net.wifi.hw/<ifname>`;
//! * [`Client`]: the client side of `os.lazy.net.wifi.v1`, the station
//!   manager `wlanmd` as `wifictl` and the front ends use it.
//!
//! The stubs are generated by `midlc`; this module adds the names, the
//! parcel framing and blocking calls that turn a structured error reply into
//! its errno.

use alloc::format;
use alloc::string::String;
use alloc::vec::Vec;

use libmessenger::{Header, Object, Parcel, VERSION};

use super::services::error_field;
use super::{registry, Endpoint, Error, Result};

/// The generated `os.lazy.net.wifi.hw.v1` stubs.
pub use messenger_generated::os_lazy_net_wifi_hw_v1 as hw;
/// The generated `os.lazy.net.wifi.v1` stubs.
pub use messenger_generated::os_lazy_net_wifi_v1 as api;

/// The station manager's registered name.
pub const NAME: &str = netpolicy::WIFI_SERVICE_NAME;

/// The registered name of the radio serving `ifname`.
pub fn hw_name(ifname: &str) -> String {
    format!("{}/{ifname}", netpolicy::WIFI_HW_NAME_PREFIX)
}

/// The interface name inside a radio's registered name, if `name` is one.
pub fn hw_ifname_of(name: &str) -> Option<&str> {
    name.strip_prefix(netpolicy::WIFI_HW_NAME_PREFIX)?
        .strip_prefix('/')
        .filter(|ifname| devmatch::valid_ifname(ifname))
}

/// A radio registered right now, held by a Wi-Fi driver identity (the
/// registry allows no one else; this checks again what it lists).
pub fn radios() -> Result<Vec<String>> {
    let mut names: Vec<String> = registry::list()?
        .into_iter()
        .filter(|entry| {
            let (Ok(uid), Ok(label)) = (
                u32::try_from(entry.owner_uid),
                u32::try_from(entry.owner_label),
            ) else {
                return false;
            };
            netpolicy::may_register_wifi_hw_name(uid, label, entry.owner_session)
        })
        .filter_map(|entry| hw_ifname_of(&entry.name).map(String::from))
        .collect();
    names.sort();
    names.dedup();
    Ok(names)
}

fn parcel(interface: u64, method: u32, body: Vec<u8>, objects: Vec<Object>) -> Parcel {
    Parcel {
        header: Header {
            version: VERSION,
            flags: 0,
            interface_id: interface,
            method,
            txn_id: 0,
            reply_to: 0,
            deadline_ns: 0,
        },
        body,
        objects,
    }
}

/// A `wifi.v1` parcel of `method` carrying `body` (the service's replies).
pub fn reply(method: u32, body: Vec<u8>) -> Parcel {
    parcel(api::INTERFACE_ID, method, body, Vec::new())
}

/// Call and turn a structured error into its errno.
fn checked(
    endpoint: &Endpoint,
    request: Parcel,
    buf: Option<&mut [u8]>,
    deadline: Option<u64>,
) -> Result<Parcel> {
    let reply = match buf {
        Some(buf) => endpoint.call_with(&request, buf, deadline)?,
        None => endpoint.call(&request, deadline)?,
    };
    match error_field(&reply)? {
        Some(code) => Err(Error::Errno(-code)),
        None => Ok(reply),
    }
}

/// Room for the reply to a request that carried a secret: those replies
/// are empty or a structured error.
const SECRET_REPLY: usize = 1024;

/// Call with a request that carries a secret (a temporal key, a
/// passphrase): encode it here into a buffer sized up front (a growing one
/// would leave copies behind in freed memory), send it, and wipe the
/// parcel's body and the encoded bytes whatever the outcome.
fn call_secret(endpoint: &Endpoint, mut request: Parcel, deadline: Option<u64>) -> Result<Parcel> {
    let mut bytes = Vec::with_capacity(request.body.len() + 256);
    let encoded = request.encode(&mut bytes).map_err(Error::Parcel);
    wipe_bytes(&mut request.body);
    let result = encoded.and_then(|()| {
        let mut buf = [0u8; SECRET_REPLY];
        endpoint.call_bytes_with(&bytes, &mut buf, deadline)
    });
    wipe_bytes(&mut bytes);
    let reply = result?;
    match error_field(&reply)? {
        Some(code) => Err(Error::Errno(-code)),
        None => Ok(reply),
    }
}

/// Scrub `bytes` with volatile writes so compiler optimizations cannot eliminate the zeroing.
pub fn wipe_bytes(bytes: &mut [u8]) {
    for byte in bytes.iter_mut() {
        // SAFETY: `byte` is a valid, aligned, exclusive reference.
        unsafe { core::ptr::write_volatile(byte, 0) };
    }
}

/// Wipe a secret held in a `String` and drop it.
pub fn wipe(text: String) {
    let mut bytes = text.into_bytes();
    wipe_bytes(&mut bytes);
}

/// A radio, as its one client sees it.
pub struct Radio {
    endpoint: Endpoint,
    /// Ticks each call may take: a wedged driver must not hang `wlanmd`.
    timeout: u64,
}

/// Entries one `ScanResults` page asks for: a page of beacons stays far
/// below the reply buffer.
pub const SCAN_PAGE: u32 = 16;
/// Entries read from one scan at most.
pub const SCAN_MAX_ENTRIES: usize = 512;

impl Radio {
    /// Resolve the radio serving `ifname`.
    pub fn connect(ifname: &str, timeout: u64) -> Result<Radio> {
        Ok(Radio {
            endpoint: registry::resolve(&hw_name(ifname))?,
            timeout,
        })
    }

    /// Give up the handle obtained by name.
    pub fn release(self) {
        let _ = self.endpoint.release();
    }

    fn call(&self, method: u32, body: Vec<u8>, objects: Vec<Object>) -> Result<Parcel> {
        let deadline = Some(crate::sys::clock() + self.timeout);
        checked(
            &self.endpoint,
            parcel(hw::INTERFACE_ID, method, body, objects),
            None,
            deadline,
        )
    }

    pub fn info(&self) -> Result<hw::HwInfo> {
        let reply = self.call(hw::METHOD_INFO, Vec::new(), Vec::new())?;
        Ok(hw::decode_info_reply(&reply.body)
            .map_err(Error::Parcel)?
            .info)
    }

    /// `Attach`, transferring `events` (a handle this task holds; gone from
    /// its table on success) for the driver to send events on.
    pub fn attach(&self, events: Endpoint) -> Result<()> {
        let (body, objects) = hw::encode_attach_args(&hw::AttachArgs {
            events: events.handle(),
        })
        .map_err(Error::Parcel)?;
        self.call(hw::METHOD_ATTACH, body, objects).map(|_| ())
    }

    pub fn detach(&self) -> Result<()> {
        self.call(hw::METHOD_DETACH, Vec::new(), Vec::new())
            .map(|_| ())
    }

    pub fn set_country(&self, alpha2: &str) -> Result<()> {
        let body = hw::encode_set_country_args(&hw::SetCountryArgs {
            alpha2: String::from(alpha2),
        })
        .map_err(Error::Parcel)?;
        self.call(hw::METHOD_SETCOUNTRY, body, Vec::new())
            .map(|_| ())
    }

    /// `Scan` every channel, actively, probing for `ssids`.
    pub fn scan(&self, ssids: Vec<Vec<u8>>) -> Result<u32> {
        let request = hw::ScanRequest {
            channels: Vec::new(),
            band: u32::MAX,
            ssids,
            active: true,
            dwell_ms: 0,
        };
        let body = hw::encode_scan_args(&hw::ScanArgs { request }).map_err(Error::Parcel)?;
        let reply = self.call(hw::METHOD_SCAN, body, Vec::new())?;
        Ok(hw::decode_scan_reply(&reply.body)
            .map_err(Error::Parcel)?
            .scan_id)
    }

    pub fn abort_scan(&self, scan_id: u32) -> Result<()> {
        let body =
            hw::encode_abort_scan_args(&hw::AbortScanArgs { scan_id }).map_err(Error::Parcel)?;
        self.call(hw::METHOD_ABORTSCAN, body, Vec::new())
            .map(|_| ())
    }

    /// Every entry of scan `scan_id`, page by page into `buf`, at most
    /// [`SCAN_MAX_ENTRIES`].
    pub fn scan_results(&self, scan_id: u32, buf: &mut [u8]) -> Result<Vec<hw::ScanEntry>> {
        let mut out = Vec::new();
        loop {
            let body = hw::encode_scan_results_args(&hw::ScanResultsArgs {
                scan_id,
                first: out.len() as u32,
                max: SCAN_PAGE,
            })
            .map_err(Error::Parcel)?;
            let request = parcel(hw::INTERFACE_ID, hw::METHOD_SCANRESULTS, body, Vec::new());
            let deadline = Some(crate::sys::clock() + self.timeout);
            let reply = checked(&self.endpoint, request, Some(buf), deadline)?;
            let page = hw::decode_scan_results_reply(&reply.body).map_err(Error::Parcel)?;
            let empty = page.results.is_empty();
            out.extend(page.results);
            if !page.more || empty || out.len() >= SCAN_MAX_ENTRIES {
                out.truncate(SCAN_MAX_ENTRIES);
                return Ok(out);
            }
        }
    }

    pub fn join(&self, bssid: [u8; 6], channel: u8, band: u32) -> Result<()> {
        let request = hw::JoinRequest {
            bssid: bssid.to_vec(),
            channel: u32::from(channel),
            band,
            width: hw::WIDTH_MHZ20,
        };
        let body = hw::encode_join_args(&hw::JoinArgs { request }).map_err(Error::Parcel)?;
        self.call(hw::METHOD_JOIN, body, Vec::new()).map(|_| ())
    }

    pub fn tx_mgmt(&self, kind: u32, frame: Vec<u8>) -> Result<()> {
        let body =
            hw::encode_tx_mgmt_args(&hw::TxMgmtArgs { kind, frame }).map_err(Error::Parcel)?;
        self.call(hw::METHOD_TXMGMT, body, Vec::new()).map(|_| ())
    }

    pub fn set_state(&self, state: u32, aid: u32) -> Result<()> {
        let body =
            hw::encode_set_state_args(&hw::SetStateArgs { state, aid }).map_err(Error::Parcel)?;
        self.call(hw::METHOD_SETSTATE, body, Vec::new()).map(|_| ())
    }

    /// `SetKey` with CCMP-128. Every copy of the key this side makes (the
    /// arguments, the encoded body, the wire bytes) is wiped as soon as the
    /// call returns.
    pub fn set_key(
        &self,
        kind: u32,
        index: u32,
        key: &[u8],
        rsc: &[u8],
        addr: &[u8],
    ) -> Result<()> {
        let mut args = hw::SetKeyArgs {
            kind,
            index,
            cipher: hw::CIPHER_CCMP128,
            key: key.to_vec(),
            rsc: rsc.to_vec(),
            addr: addr.to_vec(),
        };
        let body = hw::encode_set_key_args(&args).map_err(Error::Parcel);
        wipe_bytes(&mut args.key);
        let request = parcel(hw::INTERFACE_ID, hw::METHOD_SETKEY, body?, Vec::new());
        let deadline = Some(crate::sys::clock() + self.timeout);
        call_secret(&self.endpoint, request, deadline).map(|_| ())
    }

    pub fn leave(&self, reason: u32) -> Result<()> {
        let body = hw::encode_leave_args(&hw::LeaveArgs { reason }).map_err(Error::Parcel)?;
        self.call(hw::METHOD_LEAVE, body, Vec::new()).map(|_| ())
    }
}

/// A blocking client of `wlanmd`.
pub struct Client {
    endpoint: Endpoint,
}

impl Client {
    pub fn connect() -> Result<Client> {
        Ok(Client {
            endpoint: registry::resolve(NAME)?,
        })
    }

    fn call(&self, method: u32, body: Vec<u8>) -> Result<Parcel> {
        checked(
            &self.endpoint,
            parcel(api::INTERFACE_ID, method, body, Vec::new()),
            None,
            None,
        )
    }

    pub fn interfaces(&self) -> Result<Vec<String>> {
        let reply = self.call(api::METHOD_INTERFACES, Vec::new())?;
        Ok(api::decode_interfaces_reply(&reply.body)
            .map_err(Error::Parcel)?
            .names)
    }

    pub fn scan(&self, ifname: &str, ssids: Vec<String>) -> Result<()> {
        let body = api::encode_scan_args(&api::ScanArgs {
            ifname: String::from(ifname),
            ssids,
        })
        .map_err(Error::Parcel)?;
        self.call(api::METHOD_SCAN, body).map(|_| ())
    }

    pub fn networks(&self, ifname: &str) -> Result<Vec<api::Network>> {
        let body = api::encode_networks_args(&api::NetworksArgs {
            ifname: String::from(ifname),
        })
        .map_err(Error::Parcel)?;
        let reply = self.call(api::METHOD_NETWORKS, body)?;
        Ok(api::decode_networks_reply(&reply.body)
            .map_err(Error::Parcel)?
            .list)
    }

    /// `AddNetwork`; the passphrase crosses once, to `wlanmd`, which hands
    /// it to `keyd`. This side's copies of it (the argument, the encoded
    /// body, the wire bytes) are wiped before it returns.
    pub fn add_network(&self, profile: api::Profile, passphrase: Option<String>) -> Result<String> {
        let mut args = api::AddNetworkArgs {
            profile,
            passphrase,
        };
        let body = api::encode_add_network_args(&args).map_err(Error::Parcel);
        if let Some(text) = args.passphrase.take() {
            wipe(text);
        }
        let request = parcel(api::INTERFACE_ID, api::METHOD_ADDNETWORK, body?, Vec::new());
        let reply = call_secret(&self.endpoint, request, None)?;
        Ok(api::decode_add_network_reply(&reply.body)
            .map_err(Error::Parcel)?
            .id)
    }

    pub fn connect_network(&self, ifname: &str, id: &str) -> Result<()> {
        let body = api::encode_connect_args(&api::ConnectArgs {
            ifname: String::from(ifname),
            id: String::from(id),
        })
        .map_err(Error::Parcel)?;
        self.call(api::METHOD_CONNECT, body).map(|_| ())
    }

    pub fn disconnect(&self, ifname: &str) -> Result<()> {
        let body = api::encode_disconnect_args(&api::DisconnectArgs {
            ifname: String::from(ifname),
        })
        .map_err(Error::Parcel)?;
        self.call(api::METHOD_DISCONNECT, body).map(|_| ())
    }

    pub fn forget(&self, id: &str) -> Result<()> {
        let body = api::encode_forget_args(&api::ForgetArgs {
            id: String::from(id),
        })
        .map_err(Error::Parcel)?;
        self.call(api::METHOD_FORGET, body).map(|_| ())
    }

    pub fn status(&self, ifname: &str) -> Result<api::WifiState> {
        let body = api::encode_status_args(&api::StatusArgs {
            ifname: String::from(ifname),
        })
        .map_err(Error::Parcel)?;
        let reply = self.call(api::METHOD_STATUS, body)?;
        Ok(api::decode_status_reply(&reply.body)
            .map_err(Error::Parcel)?
            .status)
    }
}
